-- =====================================================================
-- TIS LKS Instalasi Listrik · skrip pemasangan database Supabase
-- Jalankan SEKALI di Supabase: menu SQL Editor > New query > tempel > Run
-- =====================================================================

-- 1. Tabel ------------------------------------------------------------
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  name text,
  email text,
  role text not null default 'viewer' check (role in ('admin','juri','viewer')),
  created_at timestamptz not null default now()
);

create table if not exists public.seasons (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  active boolean not null default false,
  config jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.competitors (
  id uuid primary key default gen_random_uuid(),
  season_id uuid not null references public.seasons(id) on delete cascade,
  name text not null,
  kelas text default '',
  sekolah text default '',
  peran text default '',
  sort int not null default 0,
  created_at timestamptz not null default now()
);

-- records menyimpan semua data latihan: nilai TO, kunci TO, centang jadwal, gate, jurnal
create table if not exists public.records (
  id text primary key,
  season_id uuid not null references public.seasons(id) on delete cascade,
  kind text not null check (kind in ('mark','lock','done','gate','journal')),
  ref text not null default '',
  competitor_id uuid references public.competitors(id) on delete cascade,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid()
);
create index if not exists records_season_idx on public.records(season_id);

-- 2. Fungsi peran -------------------------------------------------------
create or replace function public.my_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid()
$$;

-- profil dibuat otomatis saat pengguna baru ditambahkan; pengguna pertama menjadi admin
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, name, role)
  values (new.id, new.email, split_part(new.email,'@',1),
          case when exists (select 1 from public.profiles where role='admin') then 'viewer' else 'admin' end)
  on conflict (id) do nothing;
  return new;
end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- pengguna yang sudah ada sebelum skrip ini dijalankan juga dibuatkan profil
insert into public.profiles (id, email, name, role)
select u.id, u.email, split_part(u.email,'@',1), 'viewer' from auth.users u
on conflict (id) do nothing;
update public.profiles set role='admin'
where id = (select id from public.profiles order by created_at limit 1)
  and not exists (select 1 from public.profiles where role='admin');

-- 3. Keamanan (Row Level Security) -------------------------------------
alter table public.profiles enable row level security;
alter table public.seasons enable row level security;
alter table public.competitors enable row level security;
alter table public.records enable row level security;

drop policy if exists "profiles read" on public.profiles;
create policy "profiles read" on public.profiles for select to authenticated using (true);
drop policy if exists "profiles admin update" on public.profiles;
create policy "profiles admin update" on public.profiles for update to authenticated
  using (public.my_role()='admin') with check (public.my_role()='admin');
drop policy if exists "profiles self name" on public.profiles;
create policy "profiles self name" on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid() and role = public.my_role());

drop policy if exists "seasons read" on public.seasons;
create policy "seasons read" on public.seasons for select to authenticated using (true);
drop policy if exists "seasons admin write" on public.seasons;
create policy "seasons admin write" on public.seasons for all to authenticated
  using (public.my_role()='admin') with check (public.my_role()='admin');

drop policy if exists "competitors read" on public.competitors;
create policy "competitors read" on public.competitors for select to authenticated using (true);
drop policy if exists "competitors admin write" on public.competitors;
create policy "competitors admin write" on public.competitors for all to authenticated
  using (public.my_role()='admin') with check (public.my_role()='admin');

drop policy if exists "records read" on public.records;
create policy "records read" on public.records for select to authenticated using (true);
drop policy if exists "records juri write" on public.records;
create policy "records juri write" on public.records for all to authenticated
  using (public.my_role() in ('admin','juri')) with check (public.my_role() in ('admin','juri'));

-- 4. Sinkron langsung antar-HP (realtime) -------------------------------
do $$ begin
  begin alter publication supabase_realtime add table public.records; exception when others then null; end;
  begin alter publication supabase_realtime add table public.competitors; exception when others then null; end;
  begin alter publication supabase_realtime add table public.seasons; exception when others then null; end;
end $$;

